create table if not exists public.crm_contacts (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,client_id uuid references public.clients(id) on delete set null,full_name text not null,phone text,email text,job_title text,notes text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists public.crm_leads (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,client_id uuid references public.clients(id) on delete set null,contact_id uuid references public.crm_contacts(id) on delete set null,title text not null,source text,status text not null default 'new' check(status in('new','contacted','qualified','converted','lost')),value numeric,currency text default 'IRR',owner_id uuid references auth.users(id) on delete set null,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists public.crm_pipelines (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,is_default boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists public.crm_pipeline_stages (id uuid primary key default gen_random_uuid(),pipeline_id uuid not null references public.crm_pipelines(id) on delete cascade,name text not null,position integer not null default 0,probability numeric not null default 0 check(probability between 0 and 100),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(pipeline_id,position));
create table if not exists public.crm_deals (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,pipeline_id uuid not null references public.crm_pipelines(id) on delete restrict,stage_id uuid not null references public.crm_pipeline_stages(id) on delete restrict,client_id uuid references public.clients(id) on delete set null,contact_id uuid references public.crm_contacts(id) on delete set null,lead_id uuid references public.crm_leads(id) on delete set null,title text not null,amount numeric,currency text default 'IRR',owner_id uuid references auth.users(id) on delete set null,expected_close_date date,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists public.crm_activities (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,client_id uuid references public.clients(id) on delete set null,contact_id uuid references public.crm_contacts(id) on delete set null,lead_id uuid references public.crm_leads(id) on delete set null,deal_id uuid references public.crm_deals(id) on delete set null,assigned_to uuid references auth.users(id) on delete set null,activity_type text not null check(activity_type in('call','meeting','task','note','email')),title text not null,body text,due_at timestamptz,completed_at timestamptz,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create index if not exists crm_contacts_org_idx on public.crm_contacts(organization_id,deleted_at,updated_at desc);
create index if not exists crm_leads_org_idx on public.crm_leads(organization_id,status,deleted_at,updated_at desc);
create index if not exists crm_pipelines_org_idx on public.crm_pipelines(organization_id,deleted_at);
create index if not exists crm_stages_pipeline_idx on public.crm_pipeline_stages(pipeline_id,deleted_at,position);
create index if not exists crm_deals_org_stage_idx on public.crm_deals(organization_id,stage_id,deleted_at,updated_at desc);
create index if not exists crm_activities_org_due_idx on public.crm_activities(organization_id,deleted_at,due_at);
create or replace function public.crm_org_accessible(p_org uuid) returns boolean language sql stable security invoker set search_path=public as $$ select p_org=public.user_org_id() or exists(select 1 from public.org_connections c where c.deleted_at is null and c.status='accepted' and ((c.source_organization_id=public.user_org_id() and c.target_organization_id=p_org) or (c.target_organization_id=public.user_org_id() and c.source_organization_id=p_org))) $$;
revoke all on function public.crm_org_accessible(uuid) from public,anon; grant execute on function public.crm_org_accessible(uuid) to authenticated;
alter table public.crm_contacts enable row level security; alter table public.crm_leads enable row level security; alter table public.crm_pipelines enable row level security; alter table public.crm_pipeline_stages enable row level security; alter table public.crm_deals enable row level security; alter table public.crm_activities enable row level security;
create policy crm_contacts_select on public.crm_contacts for select to authenticated using(public.crm_org_accessible(organization_id) and public.user_role()<>'client');
create policy crm_contacts_insert on public.crm_contacts for insert to authenticated with check(organization_id=public.user_org_id() and public.user_role()<>'client');
create policy crm_contacts_update on public.crm_contacts for update to authenticated using(organization_id=public.user_org_id() and public.user_role()<>'client') with check(organization_id=public.user_org_id() and public.user_role()<>'client');
create policy crm_contacts_delete on public.crm_contacts for delete to authenticated using(organization_id=public.user_org_id() and public.user_role() in('owner','admin'));
create policy crm_leads_select on public.crm_leads for select to authenticated using(public.crm_org_accessible(organization_id) and public.user_role()<>'client');
create policy crm_leads_insert on public.crm_leads for insert to authenticated with check(organization_id=public.user_org_id() and public.user_role()<>'client');
create policy crm_leads_update on public.crm_leads for update to authenticated using(organization_id=public.user_org_id() and public.user_role()<>'client') with check(organization_id=public.user_org_id() and public.user_role()<>'client');
create policy crm_leads_delete on public.crm_leads for delete to authenticated using(organization_id=public.user_org_id() and public.user_role() in('owner','admin'));
create policy crm_pipelines_select on public.crm_pipelines for select to authenticated using(public.crm_org_accessible(organization_id) and public.user_role()<>'client');
create policy crm_pipelines_insert on public.crm_pipelines for insert to authenticated with check(organization_id=public.user_org_id() and public.user_role() in('owner','admin','broker'));
create policy crm_pipelines_update on public.crm_pipelines for update to authenticated using(organization_id=public.user_org_id() and public.user_role() in('owner','admin','broker')) with check(organization_id=public.user_org_id() and public.user_role() in('owner','admin','broker'));
create policy crm_pipelines_delete on public.crm_pipelines for delete to authenticated using(organization_id=public.user_org_id() and public.user_role() in('owner','admin'));
create policy crm_stages_select on public.crm_pipeline_stages for select to authenticated using(exists(select 1 from public.crm_pipelines p where p.id=pipeline_id and public.crm_org_accessible(p.organization_id) and public.user_role()<>'client'));
create policy crm_stages_insert on public.crm_pipeline_stages for insert to authenticated with check(exists(select 1 from public.crm_pipelines p where p.id=pipeline_id and p.organization_id=public.user_org_id() and public.user_role() in('owner','admin','broker')));
create policy crm_stages_update on public.crm_pipeline_stages for update to authenticated using(exists(select 1 from public.crm_pipelines p where p.id=pipeline_id and p.organization_id=public.user_org_id() and public.user_role() in('owner','admin','broker'))) with check(exists(select 1 from public.crm_pipelines p where p.id=pipeline_id and p.organization_id=public.user_org_id() and public.user_role() in('owner','admin','broker')));
create policy crm_stages_delete on public.crm_pipeline_stages for delete to authenticated using(exists(select 1 from public.crm_pipelines p where p.id=pipeline_id and p.organization_id=public.user_org_id() and public.user_role() in('owner','admin')));
create policy crm_deals_select on public.crm_deals for select to authenticated using(public.crm_org_accessible(organization_id) and public.user_role()<>'client');
create policy crm_deals_insert on public.crm_deals for insert to authenticated with check(organization_id=public.user_org_id() and public.user_role()<>'client');
create policy crm_deals_update on public.crm_deals for update to authenticated using(organization_id=public.user_org_id() and public.user_role()<>'client') with check(organization_id=public.user_org_id() and public.user_role()<>'client');
create policy crm_deals_delete on public.crm_deals for delete to authenticated using(organization_id=public.user_org_id() and public.user_role() in('owner','admin'));
create policy crm_activities_select on public.crm_activities for select to authenticated using(public.crm_org_accessible(organization_id) and public.user_role()<>'client');
create policy crm_activities_insert on public.crm_activities for insert to authenticated with check(organization_id=public.user_org_id() and public.user_role()<>'client');
create policy crm_activities_update on public.crm_activities for update to authenticated using(organization_id=public.user_org_id() and public.user_role()<>'client') with check(organization_id=public.user_org_id() and public.user_role()<>'client');
create policy crm_activities_delete on public.crm_activities for delete to authenticated using(organization_id=public.user_org_id() and public.user_role() in('owner','admin'));
do $$ declare t text; begin foreach t in array array['crm_contacts','crm_leads','crm_pipelines','crm_pipeline_stages','crm_deals','crm_activities'] loop execute format('drop trigger if exists block_audit_guest_writes_%I on public.%I',t,t); execute format('create trigger block_audit_guest_writes_%I before insert or update or delete on public.%I for each row execute function public.block_audit_guest_writes()',t,t); execute format('drop trigger if exists audit_%I on public.%I',t,t); execute format('create trigger audit_%I after insert or update or delete on public.%I for each row execute function public.record_audit_event()',t,t); end loop; end $$;